import 'dart:io';

const _source = 'tool/eff_large_wordlist.txt';
const _target = 'lib/feature/sessions/wordlist.dart';
final _word = RegExp(r'^[a-z]+$');

void main() {
  final words = <String>{};
  for (final line in File(_source).readAsLinesSync()) {
    final word = line.split('\t').last.trim().toLowerCase();
    if (_word.hasMatch(word)) words.add(word);
  }
  final output = StringBuffer()
    ..writeln(
      '// Generated by tool/gen_wordlist.dart from the EFF large wordlist',
    )
    ..writeln('// (CC BY 3.0, https://www.eff.org/dice). Do not edit.')
    ..writeln()
    ..writeln('const effWords = <String>[');
  for (final word in words) {
    output.writeln("  '$word',");
  }
  output.writeln('];');
  File(_target).writeAsStringSync(output.toString());
  stdout.writeln('Wrote ${words.length} words to $_target');
}
